{
  "interpretation": {
    "name": "TightenAndReturnNR7OnLine1",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners on line 1 (variant F25) with tool NR7, evaluate the torques against the program, record the result, and return NR7 to the crib.",
    "constraints": [
      "NR7 must be reserved before any use and released after it has been returned to the crib",
      "NR7 must be at station st1 before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program (no literal torque, tolerance or bolt count)",
      "The tightening must be evaluated against its program and recorded for traceability",
      "The transport of NR7 must be delegated to agvexecutor",
      "NR7 must be returned to the crib after the evaluation and recording are complete"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "One-shot execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tighten-evaluate-record-return",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "getProgram", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {"name": "transportToStation", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["reserve", "getProgram"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["reserve", "configure"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Quality",
        "next": "ReturnTool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "getProgram"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "ReturnTool",
        "next": null,
        "steps": [
          {"name": "transportToCrib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
